head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL50210N";

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil50210n.onpageload' });
    }
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_20", entity: "dlt_comList", countIds: [], cells: [{ childId: "option_21", fn: function (v, i) { return String(v("bzProcsNo")); } }, { childId: "__rc0", fn: function (v, i) { return String(v("comNm")) + "(" + String(v("isurCd")) + ")"; } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        form = (document.clmSchdlNotiForm || { elements: [] });
        idInfoArr = [];
        loadTp = 'null';
        isOk = 'null';
        await scwin.checkSave();
        for (let i = 0; i < dlt_idInfoList.getRowCount(); i++) {
            idInfoArr[i] = new idInfo((String(((dlt_idInfoList.getCellData(i, "integ_usr_id") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].integ_usr_id"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "integ_usr_id") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].integ_usr_id"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_idInfoList.getCellData(i, "integ_usr_id") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].integ_usr_id"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "integ_usr_id") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].integ_usr_id"); })())))), (String(((dlt_idInfoList.getCellData(i, "corp_usr_nm") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].corp_usr_nm"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "corp_usr_nm") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].corp_usr_nm"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_idInfoList.getCellData(i, "corp_usr_nm") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].corp_usr_nm"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "corp_usr_nm") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].corp_usr_nm"); })())))), (String(((dlt_idInfoList.getCellData(i, "email") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].email"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "email") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].email"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_idInfoList.getCellData(i, "email") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].email"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "email") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].email"); })())))), (String(((dlt_idInfoList.getCellData(i, "tel_no") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].tel_no"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "tel_no") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].tel_no"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_idInfoList.getCellData(i, "tel_no") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].tel_no"); })())) == null ? '' : ((dlt_idInfoList.getCellData(i, "tel_no") ?? (() => { throw new Error("unresolved:" + "idInfoList[__i].tel_no"); })())))));
        }
        $c.util.getComponent("ipt_userNm").setValue(idInfoArr[0].usr_nm);
        $c.util.getComponent("ipt_telNo").setValue(idInfoArr[0].tel_no);
        $c.util.getComponent("ipt_email").setValue(idInfoArr[0].email);

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil50210n.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_integUsrId_onchange
 * @description slc_integUsrId 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_integUsrId_onchange = function(e){
    try {
        scwin.setIdInfo();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil50210n.slc_integUsrId_onchange' }); }
};

/**
 * @method
 * @name rd_gongmoYN_onclick
 * @description rd_gongmoYN 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_gongmoYN_onclick = function(e){
    try {
        scwin.setProcess('__self.value')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil50210n.rd_gongmoYN_onclick' }); }
};

/**
 * @method
 * @name btn_doAssgn_onclick
 * @description btn_doAssgn 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_doAssgn_onclick = async function(e){
    try {
        await scwin.doAssgn()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil50210n.btn_doAssgn_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_doAssgn
 * @description do Assgn 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_doAssgn = async function () {
    const sbmOptions = {
        id: "tx_doAssgn",
        method: "post",
        action: "/listInvstg/idAssgnPop.do",
        ref: "dma_doAssgnReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/listInvstg/idAssgnPop.do",
        ref: "dma_loadListReq",
        target: "dlt_comList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkSave
 * @description check Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSave = async function () {
    const bzProcsNo = 'null';
    if (loadTp === '1') {
        if (isOk !== 'true') {
            await $c.win.alert('오류발생');
        } else {
            await $c.win.alert('저장되었습니다.');
            (function () { const o = $c.win.getOpenerScope(); if (o) { $c.win.setPageFrameSrc($c.win.getFrame(o), null); } else { /* TODO Stage2: [sdd] 부모 창을 못 찾았다 — 새로고침하지 않는다(자기 화면을 다시 열면 무한 고리가 된다) */ } })();
            this.close();
        }
    }
    if (loadTp !== '0') {

    }
};

/**
 * @method
 * @name setDataVars
 * @description set Data Vars 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.setDataVars = function (ver) {
    setLeadcomVars();
    setDates();
    if (ver === '1') {
        scwin.setDisable();
    } else {
        if (ver === '2' || ver === '3') {
            scwin.setFileDisable();
        }
    }
};

/**
 * @method
 * @name setDisable
 * @description set Disable 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDisable = function () {
    for (let i = 0; i < form.length; i++) {
        form[i].disabled = true;
    }
};

/**
 * @method
 * @name setFileDisable
 * @description set File Disable 처리
 * @returns {void}
 * @hidden N
 */
scwin.setFileDisable = function () {
    const obj1 = form['attachFiles[0]'];
    const obj2 = form['attachFiles[1]'];
    obj1.disabled = true;
    obj2.disabled = true;
};

/**
 * @method
 * @name doAssgn
 * @description do Assgn 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doAssgn = async function () {
    form.action = '/listInvstg/idAssgnPop.do';
    const option = $c.util.getComponent('slc_bzProcsNo').options;
    const comName = option[option.getSelectedIndex()].text;
    const usrId = $c.util.getComponent('slc_integUsrId').getValue();
    if (await scwin.checkValue()) {
        if (await $c.win.confirm('[' + comName + '] 회사를 ID [' + usrId + '] 에 배정 하시겠습니까?')) {
            await scwin.tx_doAssgn();
        }
    }
};

/**
 * @method
 * @name checkValue
 * @description check Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkValue = async function () {
    const gongmoYN = $c.util.getComponent('dma_doAssgnReq').get('pubofrYN');
    if ($c.util.getComponent('slc_bzProcsNo').getValue() === '') {
        await $c.win.alert('법인을 선택하십시오.');
        return false;
    }
    if (gongmoYN === "") {
        await $c.win.alert("공모여부를 선택하여 주시기 바랍니다.");
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name doChangeChrg
 * @description do Change Chrg 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doChangeChrg = async function () {
    if (await $c.win.confirm('선택한 담당자가 아닌 로그인한 담당자의 정보를 변경합니다.\r\n담당자정보 변경을 하시겠습니까?')) {
        $c.win.setPageFrameSrc($c.win.getFrame(), '/ui/jsp/JLDFIL25100.xml');
        this.close();
    }
};

/**
 * @method
 * @name setIdInfo
 * @description set Id Info 처리
 * @returns {void}
 * @hidden N
 */
scwin.setIdInfo = function () {
    const idx = $c.util.getComponent('slc_integUsrId').getSelectedIndex();
    $c.util.getComponent("ipt_userNm").setValue(idInfoArr[idx].usr_nm);
    $c.util.getComponent("ipt_telNo").setValue(idInfoArr[idx].tel_no);
    $c.util.getComponent("ipt_email").setValue(idInfoArr[idx].email);
};

/**
 * @method
 * @name setProcess
 * @description set Process 처리
 * @param {*} value value
 * @returns {void}
 * @hidden N
 */
scwin.setProcess = function (value) {
    $c.util.getComponent('dma_doAssgnReq').set('pubofrYN', value);
};
